{"cards": [{"node_code": "N_438ff0a7748ecb74", "definition": "研究材料化学成分、物相组成、微观组织及晶体结构的检测与分析技术，涵盖从宏观成分到微观形貌的多尺度表征方法。", "boundary": "聚焦于静态或准静态下材料内部状态信息的获取。包括化学分析、显微观察、晶体学分析及三维结构重建。侧重于“是什么”和“长什么样”的定性或定量描述，不涉及材料在动态载荷或环境下的性能响应测试，也不涉及基于表征结果的失效机理推导。", "includes": ["化学成分定量与定性分析（如光谱、色谱）", "显微组织、晶粒尺寸、相分布及晶体取向表征", "孔隙、裂纹、界面等微观缺陷及三维结构成像技术"], "excludes": ["材料在受力或环境作用下的性能测试（归材料性能与环境试验）", "基于表征数据的失效根因分析或寿命预测（归失效分析与材料完整性）"], "sibling_distinctions": [{"other_code": "N_ab33f0dc89e0a1fc", "rule": "本节点关注材料静态内部结构信息的获取；性能试验节点关注材料在特定条件（力、热、环境）下的响应行为。"}, {"other_code": "N_483f1ae9e28d44cf", "rule": "本节点提供表征数据作为证据；失效分析节点利用这些数据进行逻辑推理和根因判定。"}], "cross_boundary_rule": "若研究重点在于开发新的表征手段或提高结构解析精度，归本节点；若重点在于利用表征结果解释失效过程或评估剩余寿命，归失效分析节点。"}, {"node_code": "N_ab33f0dc89e0a1fc", "definition": "研究材料在力学、热物理、功能特性及环境作用下的性能测试方法、标准及加速老化试验技术。", "boundary": "聚焦于材料在特定外部条件（载荷、温度、介质等）下的响应行为及性能参数测定。包括拉伸、疲劳、硬度等力学测试，导热、导电等功能测试，以及腐蚀、老化等环境试验。侧重于“表现如何”的量化评估，不涉及材料内部微观结构的直接成像，也不涉及失效后的根因追溯。", "includes": ["力学性能（强度、硬度、疲劳、蠕变）测试方法与标准", "热物理（导热、热膨胀）及电、磁、声等功能性能测试", "腐蚀、氧化、老化等环境加速试验及性能衰减评估"], "excludes": ["材料微观组织、成分及晶体结构的静态表征（归成分、组织与结构表征）", "基于试验数据的失效模式识别与根因分析（归失效分析与材料完整性）"], "sibling_distinctions": [{"other_code": "N_438ff0a7748ecb74", "rule": "本节点关注材料在外部激励下的动态或稳态响应；结构表征节点关注材料无激励或静态下的内部状态。"}, {"other_code": "N_483f1ae9e28d44cf", "rule": "本节点提供性能数据；失效分析节点利用性能数据结合其他证据进行失效诊断。"}], "cross_boundary_rule": "若试验目的是获取材料固有性能参数或验证材料选型，归本节点；若试验目的是复现失效场景或验证失效机理，归失效分析节点。"}, {"node_code": "N_483f1ae9e28d44cf", "definition": "研究基于多源证据的失效模式识别、机理分析、根因追溯及材料完整性评估方法，涵盖断口形貌分析与证据链构建。", "boundary": "聚焦于“为什么失效”及“如何评估剩余寿命”的诊断与评估过程。综合运用成分、结构、性能等表征数据，结合现场调查，进行逻辑推理。侧重于分析流程、证据整合及结论报告，而非单一表征技术的开发或单一性能参数的测定。", "includes": ["断口、磨损、腐蚀形貌的微观分析与失效特征识别", "失效模式、机理及根本原因（Root Cause）的系统分析", "取样策略、证据链构建、完整性评估及分析报告编制"], "excludes": ["单纯的成分、组织或性能测试方法研究（归成分、组织与结构表征或材料性能与环境试验）", "纯理论力学模型推导或纯数值模拟（归力学或设计节点，除非作为失效分析的工具）"], "sibling_distinctions": [{"other_code": "N_438ff0a7748ecb74", "rule": "本节点利用表征数据进行综合诊断；结构表征节点提供基础数据。"}, {"other_code": "N_ab33f0dc89e0a1fc", "rule": "本节点利用性能数据进行失效验证；性能试验节点提供基础数据。"}], "cross_boundary_rule": "若工作核心是建立新的表征或测试标准，归相应表征或试验节点；若核心是整合数据解决具体失效案例或评估结构完整性，归本节点。"}]}
